def finance_compound_interest():
    try:
        p=float(input('Principal: ')); r=float(input('Rate %: '))/100; n=float(input('Times/year: ')); t=float(input('Years: ')); return 'Compound Amount = ' + str(round(p*(1+r/n)**(n*t),2))
    except:
        return 'Invalid input'.format("compound_interest")

def finance_simple_interest():
    try:
        p=float(input('Principal: ')); r=float(input('Rate %: '))/100; t=float(input('Time (years): ')); return 'Simple Interest = ' + str(p*r*t)
    except:
        return 'Invalid input'.format("simple_interest")

def finance_loan_payment():
    try:
        p=float(input('Principal: ')); r=float(input('Rate %: '))/100/12; n=int(input('Months: ')); m=p*r*(1+r)**n/((1+r)**n-1) if r else p/n; return 'Monthly Payment = ${:.2f}'.format(m)
    except:
        return 'Invalid input'.format("loan_payment")

def finance_amortization():
    try:
        p=float(input('Principal: ')); r=float(input('Rate %: '))/100/12; n=int(input('Months: ')); m=p*r*(1+r)**n/((1+r)**n-1) if r else p/n; return 'Amortization: ${:.2f}/mo for {}mo = ${:.2f} total'.format(m,n,m*n)
    except:
        return 'Invalid input'

def finance_future_value():
    try:
        pv=float(input('Present Value: ')); r=float(input('Rate %: '))/100; n=int(input('Periods: ')); return 'Future Value = ' + str(round(pv*(1+r)**n,2))
    except:
        return 'Invalid input'.format("future_value")

def finance_present_value():
    try:
        fv=float(input('Future Value: ')); r=float(input('Rate %: '))/100; n=int(input('Periods: ')); return 'Present Value = ' + str(round(fv/(1+r)**n,2))
    except:
        return 'Invalid input'.format("present_value")

