def color_rgb_to_hex():
    try:
        r=int(input('R(0-255): ')); g=int(input('G(0-255): ')); b=int(input('B(0-255): ')); return '#' + format(r,'02x') + format(g,'02x') + format(b,'02x')
    except:
        return 'Invalid input'.format("rgb_to_hex")

def color_hex_to_rgb():
    try:
        h=input('Hex (#RRGGBB): ').lstrip('#'); return 'RGB({},{},{})'.format(int(h[0:2],16), int(h[2:4],16), int(h[4:6],16))
    except:
        return 'Invalid input'.format("hex_to_rgb")

def color_rgb_to_hsl():
    try:
        r=int(input('R(0-255): '))/255; g=int(input('G(0-255): '))/255; b=int(input('B(0-255): '))/255
        mx=max(r,g,b); mn=min(r,g,b); l=(mx+mn)/2
        if mx==mn: s=0; h=0
        else: s=(mx-mn)/(1-abs(2*l-1)); c=mx-mn
        if mx==mn: pass
        elif mx==r: h=60*((g-b)/c%6)
        elif mx==g: h=60*((b-r)/c+2)
        else: h=60*((r-g)/c+4)
        h=(h+360)%360
        return 'HSL({:.0f},{:.1f}%,{:.1f}%)'.format(h,s*100,l*100)
    except:
        return 'Invalid input'

def color_hsl_to_rgb():
    try:
        h=float(input('H(0-360): ')); s=float(input('S%(0-100): '))/100; l=float(input('L%(0-100): '))/100; c=(1-abs(2*l-1))*s; x=c*(1-abs((h/60)%2-1)); m=l-c/2; i=int(h/60)%6; t=[(c,x,0),(x,c,0),(0,c,x),(0,x,c),(x,0,c),(c,0,x)][i]; return 'RGB({:.0f},{:.0f},{:.0f})'.format((t[0]+m)*255,(t[1]+m)*255,(t[2]+m)*255)
    except:
        return 'Invalid input'.format("hsl_to_rgb")

def color_rgb_to_cmyk():
    try:
        r=int(input('R(0-255): '))/255; g=int(input('G(0-255): '))/255; b=int(input('B(0-255): '))/255; k=1-max(r,g,b); return 'CMYK({:.2f},{:.2f},{:.2f},{:.2f})'.format((1-r-k)/(1-k) if k<1 else 0,(1-g-k)/(1-k) if k<1 else 0,(1-b-k)/(1-k) if k<1 else 0,k)
    except:
        return 'Invalid input'.format("rgb_to_cmyk")

def color_cmyk_to_rgb():
    try:
        c=float(input('C(0-1): ')); m=float(input('M(0-1): ')); y=float(input('Y(0-1): ')); k=float(input('K(0-1): ')); return 'RGB({:.0f},{:.0f},{:.0f})'.format(255*(1-c)*(1-k),255*(1-m)*(1-k),255*(1-y)*(1-k))
    except:
        return 'Invalid input'.format("cmyk_to_rgb")

